#!/bin/sh
# Print the Homebrew formula for a release from GoReleaser's checksums.txt.
# usage: scripts/formula.sh VERSION dist/checksums.txt > Formula/ccfleet.rb
set -eu
v=$1 sums=$2
sha() { awk -v f="ccfleet_${v}_$1.tar.gz" '$2 == f { print $1 }' "$sums"; }
url="https://github.com/jdbrewer/ccfleet/releases/download/v${v}"
cat <<RUBY
# Generated by scripts/formula.sh on release; edit that script, not this file.
class Ccfleet < Formula
  desc "Quiet board for all your Claude Code sessions in tmux"
  homepage "https://github.com/jdbrewer/ccfleet"
  version "${v}"
  license "MIT"

  depends_on "tmux"

  on_macos do
    on_arm do
      url "${url}/ccfleet_${v}_darwin_arm64.tar.gz"
      sha256 "$(sha darwin_arm64)"
    end
    on_intel do
      url "${url}/ccfleet_${v}_darwin_amd64.tar.gz"
      sha256 "$(sha darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "${url}/ccfleet_${v}_linux_arm64.tar.gz"
      sha256 "$(sha linux_arm64)"
    end
    on_intel do
      url "${url}/ccfleet_${v}_linux_amd64.tar.gz"
      sha256 "$(sha linux_amd64)"
    end
  end

  def install
    bin.install "ccfleet"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ccfleet --version")
  end
end
RUBY
